 function apply(action,p={}){const record=stateRef.current.cases.find(x=>x.id===(p.id||c?.id));if(!record)throw Error('Case not found.');if(record.server){return saveAction(record,action,{field,...p}).then(updated=>{replaceCase(updated);setModal(null);toast.success('Decision saved.');return updated}).catch(e=>{toast.error(e.message);throw e})}const updated=updateCase(record,action,{field,...p});setState(prev=>({...prev,cases:prev.cases.map(x=>x.id===updated.id?updated:x)}));setModal(null);if(['verify','resolve','sample-support'].includes(action)){const k=pending(updated)[0];if(k)setField(k);toast.success(k?'Saved. Continue with the next issue.':'Review saved. Your results are ready.')}return updated}

