   setLiveProgress({phase:result.remaining?'paused':result.errors.length?'failed':'complete',title:result.remaining?'Processing paused':result.errors.length?'Batch finished with retry needed':'Batch processing complete',detail:`${result.finished-result.errors.length} finished · ${result.remaining} waiting · ${result.errors.length} need retry · ${duration} processing elapsed (includes file reading and network)`,current:result.finished,total:records.length});
